/**
 * pricing-analysis.js — /dashboards/pricing-analysis.html (admin only).
 *
 * The page itself is static, generated by scripts/build-pricing-analysis.py. The only
 * behaviour it needs is the sticky section nav: highlight whichever section is currently
 * in view so a long, dense page keeps its place indicator honest.
 *
 * Deliberately does NOT fetch anything. There is no API behind this page — the figures
 * come from ShopWorks ODBC pulls that are not in Caspio, so they are rendered into the
 * gated HTML at build time rather than served as JSON (a JSON under /dashboards would be
 * world-readable; only *.html goes through gateStaffPage).
 *
 * Why rects and not IntersectionObserver: with tall sections several are on screen at
 * once, so "is it intersecting" cannot decide which one you are reading. The rule that
 * matches what a reader expects is "the last heading that has scrolled past the nav bar",
 * and that needs the actual offsets. Reads are batched into a rAF so the scroll thread
 * stays clean.
 */
(function () {
    'use strict';

    var links = Array.prototype.slice.call(document.querySelectorAll('.pa-nav-link'));
    if (!links.length) return;

    var sections = links
        .map(function (a) {
            var el = document.getElementById(a.getAttribute('href').slice(1));
            return el ? { link: a, el: el } : null;
        })
        .filter(Boolean);
    if (!sections.length) return;

    var nav = document.querySelector('.pa-nav');
    var active = null;
    var queued = false;

    function update() {
        queued = false;
        // A little below the bar, so a heading counts as current once it is properly clear of it.
        var line = (nav ? nav.getBoundingClientRect().height : 0) + 24;
        var current = sections[0];

        for (var i = 0; i < sections.length; i++) {
            if (sections[i].el.getBoundingClientRect().top <= line) current = sections[i];
        }
        // At the very bottom the last section may never cross the line — claim it anyway,
        // otherwise the marker sticks one short for the whole final screenful.
        if (window.innerHeight + window.scrollY >= document.body.scrollHeight - 4) {
            current = sections[sections.length - 1];
        }
        if (current === active) return;
        if (active) active.link.classList.remove('is-active');
        current.link.classList.add('is-active');
        active = current;
    }

    function onScroll() {
        if (queued) return;
        queued = true;
        window.requestAnimationFrame(update);
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll, { passive: true });
    update();
})();
